import { describe, expect, it } from 'vitest';
import { buildOrderMessage, whatsappUrl } from './whatsapp.js';
describe('WhatsApp checkout', () => { const message = buildOrderMessage({ reference: 'MOD-TEST', items: [{ name: 'Celeste Dress', sku: 'SKU-S', size: 'S', color: 'Black', quantity: 2, unitPrice: 100, lineTotal: 200 }], currency: 'LKR', subtotal: 200, deliveryFee: 0, total: 200, customer: { name: 'Ada', phone: '0770000000', address: '10 Main Street', city: 'Colombo' } }); it('includes the order snapshot without claiming confirmation', () => { expect(message).toContain('Order Reference: MOD-TEST'); expect(message).toContain('Size: S'); expect(message).toContain('Estimated Total: LKR 200.00'); expect(message).not.toContain('confirmed order'); }); it('builds an official encoded URL', () => { const url = whatsappUrl('94770000000', message); expect(url).toMatch(/^https:\/\/wa\.me\/94770000000\?text=/); expect(url).toContain('%0A'); }); });
